<template>
  <div class="settings-page">
    <header><router-link to="/" class="brand">MIROFISH</router-link><router-link to="/">返回首页 ↗</router-link></header>
    <main>
      <div class="heading"><div><p>SETTINGS / MODEL ROUTING</p><h1>模型配置</h1></div><button :disabled="saving" @click="apply">应用配置</button></div>
      <div v-if="notice" class="notice" :data-error="noticeError">{{ notice }}</div>
      <section>
        <div class="section-title"><div><small>01</small><h2>三个模型职责</h2></div><span>新任务使用新配置，已有项目保留快照</span></div>
        <div class="role-grid">
          <article v-for="role in roles" :key="role.key">
            <div class="role-mark">{{ role.number }}</div><h3>{{ role.title }}</h3><p>{{ role.description }}</p>
            <label>Provider 连接<select v-model="draft[role.key].connection_id" @change="refreshModels(role.key)"><option value="">请选择</option><option v-for="item in compatibleConnections(role.key)" :key="item.connection_id" :value="item.connection_id">{{ item.name }}</option></select></label>
            <label>模型名称<div class="model-select-row"><select v-model="draft[role.key].model" :disabled="modelStates[role.key].loading || !draft[role.key].connection_id"><option value="">{{ modelStates[role.key].loading ? '正在加载模型…' : '请选择模型' }}</option><option v-if="draft[role.key].model && !modelStates[role.key].models.some(item=>item.id===draft[role.key].model)" :value="draft[role.key].model">{{ draft[role.key].model }}（当前不可用）</option><option v-for="model in modelStates[role.key].models" :key="model.id" :value="model.id">{{ model.id }} · {{ model.capability === 'embedding' ? 'Embedding' : '文本' }}</option></select><button type="button" :disabled="modelStates[role.key].loading || !draft[role.key].connection_id" @click="refreshModels(role.key)">刷新</button></div><span v-if="modelStates[role.key].error" class="field-error">{{ modelStates[role.key].error }}</span></label>
            <details><summary>高级参数</summary><div class="advanced"><label v-if="role.key === 'embedding'">向量维度<input v-model.number="draft[role.key].dimensions" type="number" min="1"></label><label>超时（秒）<input v-model.number="draft[role.key].timeout" type="number" min="1"></label><label v-if="role.key !== 'embedding'">最大并发<input v-model.number="draft[role.key].max_concurrency" type="number" min="1"></label><label v-if="role.key === 'high_throughput'" class="check"><input v-model="draft[role.key].fallback_enabled" type="checkbox">失败时回退高能力模型</label></div></details>
          </article>
        </div>
        <button class="save-draft" :disabled="saving" @click="save">保存草稿</button>
      </section>
      <section>
        <div class="section-title"><div><small>02</small><h2>Provider 连接</h2></div><span>密钥保存后不可回读</span></div>
        <form class="connection-form" @submit.prevent="addConnection"><input v-model.trim="newConnection.name" required placeholder="连接名称"><select v-model="newConnection.connection_type"><option value="openai_compatible">在线 OpenAI-compatible</option><option value="local_openai">本地文本模型</option><option value="embedding">Embedding 服务</option><option value="codex_gateway">Codex Gateway</option><option value="direct_oauth_gateway">Direct OAuth Gateway</option></select><input v-model.trim="newConnection.base_url" required placeholder="Base URL"><input v-model="newConnection.api_key" type="password" autocomplete="new-password" placeholder="API Key（可选）"><button>新增连接</button></form>
        <div class="connections"><article v-for="item in connections" :key="item.connection_id"><div><strong>{{ item.name }}</strong><span>{{ item.connection_type }}</span><code>{{ item.base_url }}</code></div><div><span>{{ item.api_key_masked || (item.connection_type.includes('oauth') ? oauthAccountLabel : '无需密钥') }}</span><span v-if="testStates[item.connection_id]?.message" class="test-result" :data-status="testStates[item.connection_id].status" aria-live="polite">{{ testStates[item.connection_id].message }}</span><span v-if="deleteStates[item.connection_id]?.message" class="test-result" data-status="failed" role="alert">{{ deleteStates[item.connection_id].message }}</span><button v-if="item.connection_type.includes('oauth') && !oauthAccount.authenticated" @click="startOAuth">登录 ChatGPT</button><button v-if="item.connection_type.includes('oauth') && oauthAccount.authenticated" @click="logoutOAuth">退出登录</button><button :disabled="testStates[item.connection_id]?.status === 'testing'" @click="testConnection(item)">{{ testStates[item.connection_id]?.status === 'testing' ? '测试中…' : '测试' }}</button><button :disabled="deleteStates[item.connection_id]?.status === 'deleting'" @click="removeConnection(item)">{{ deleteStates[item.connection_id]?.status === 'deleting' ? '删除中…' : '删除' }}</button></div><div v-if="item.connection_type.includes('oauth') && oauthLogin.status === 'waiting'" class="oauth-panel"><strong>授权 ChatGPT</strong><span>代码：<code>{{ oauthLogin.user_code }}</code></span><button @click="copyOAuthCode">复制代码</button><a :href="oauthLogin.verification_uri" target="_blank" rel="noopener">打开授权页面 ↗</a><span>等待授权…</span></div></article></div>
      </section>
    </main>
  </div>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { applyModelDraft, cancelChatGptLogin, createModelConnection, deleteModelConnection, getChatGptAccount, getChatGptLoginStatus, getConnectionModels, getModelConnections, getModelDraft, logoutChatGpt, saveModelDraft, startChatGptLogin, testModelConnection } from '../api/modelSettings'
const connections = ref([]), saving = ref(false), notice = ref(''), noticeError = ref(false)
const testStates = reactive({})
const deleteStates = reactive({})
const oauthAccount = reactive({authenticated:false,email:null,plan:null})
const oauthLogin = reactive({status:'idle',login_id:null,user_code:null,verification_uri:null})
const modelStates = reactive({embedding:{loading:false,models:[],error:''},high_capability:{loading:false,models:[],error:''},high_throughput:{loading:false,models:[],error:''}})
let oauthTimer = null
const oauthAccountLabel = computed(()=>oauthAccount.authenticated ? `${oauthAccount.email || '已登录'} · ${oauthAccount.plan || ''}` : '未登录')
const roles = [{key:'embedding',number:'01',title:'Embedding',description:'向量写入与语义检索'}, {key:'high_capability',number:'02',title:'高能力模型',description:'本体、人设、规划、报告与问答'}, {key:'high_throughput',number:'03',title:'高吞吐模型',description:'图谱抽取、正式模拟与记忆回写'}]
const draft = reactive({embedding:{connection_id:'',model:'',dimensions:384,timeout:60},high_capability:{connection_id:'',model:'',timeout:600,max_concurrency:2},high_throughput:{connection_id:'',model:'',timeout:600,max_concurrency:8,fallback_enabled:true}})
const newConnection = reactive({name:'',connection_type:'openai_compatible',base_url:'',api_key:''})
const compatibleConnections = role => connections.value.filter(item => role === 'embedding' ? item.connection_type === 'embedding' : item.connection_type !== 'embedding')
const roleNames = {embedding:'Embedding',high_capability:'高能力模型',high_throughput:'高吞吐模型'}
const rolesUsingConnection = connectionId => Object.entries(draft).filter(([,config])=>config.connection_id===connectionId).map(([role])=>roleNames[role])
async function load(){ const [c,d]=await Promise.all([getModelConnections(),getModelDraft()]);connections.value=c.data||[];Object.entries(d.data||{}).forEach(([key,value])=>Object.assign(draft[key],value));await Promise.all(roles.map(role=>refreshModels(role.key))) }
async function refreshModels(role){const connectionId=draft[role].connection_id;if(!connectionId){modelStates[role]={loading:false,models:[],error:''};return}modelStates[role].loading=true;modelStates[role].error='';try{const result=await getConnectionModels(connectionId,role);modelStates[role].models=result.data||[]}catch(e){modelStates[role].models=[];modelStates[role].error=e.response?.data?.error||e.message||'模型列表加载失败'}finally{modelStates[role].loading=false}}
async function save(){saving.value=true;try{await saveModelDraft(draft);notice.value='草稿已保存';noticeError.value=false}catch(e){notice.value=e.message;noticeError.value=true}finally{saving.value=false}}
async function apply(){saving.value=true;try{await saveModelDraft(draft);await applyModelDraft();notice.value='配置已应用，新任务将使用新版本';noticeError.value=false}catch(e){notice.value=e.message;noticeError.value=true}finally{saving.value=false}}
async function addConnection(){await createModelConnection({...newConnection,is_local:newConnection.connection_type.includes('local')||newConnection.connection_type==='embedding'});Object.assign(newConnection,{name:'',connection_type:'openai_compatible',base_url:'',api_key:''});await load()}
async function removeConnection(item){const usedBy=rolesUsingConnection(item.connection_id);if(usedBy.length){deleteStates[item.connection_id]={status:'failed',message:`无法删除：正在被 ${usedBy.join('、')} 使用`};return}if(!window.confirm(`确定删除连接“${item.name}”吗？`))return;deleteStates[item.connection_id]={status:'deleting',message:''};try{await deleteModelConnection(item.connection_id);delete deleteStates[item.connection_id];notice.value=`${item.name} 已删除`;noticeError.value=false;await load()}catch(e){const message=e.response?.data?.error||e.message||'删除失败';deleteStates[item.connection_id]={status:'failed',message};notice.value=message;noticeError.value=true}}
async function testConnection(item){testStates[item.connection_id]={status:'testing',message:'正在测试连接…'};try{const result=await testModelConnection(item.connection_id);const message=`测试通过 · ${result.data.latency_ms}ms`;testStates[item.connection_id]={status:'passed',message};notice.value=`${item.name} ${message}`;noticeError.value=false}catch(e){testStates[item.connection_id]={status:'failed',message:'测试失败'};notice.value=e.message;noticeError.value=true}}
async function refreshOAuthAccount(){try{const result=await getChatGptAccount();Object.assign(oauthAccount,result.data||{})}catch{Object.assign(oauthAccount,{authenticated:false,email:null,plan:null})}}
async function startOAuth(){const result=await startChatGptLogin();Object.assign(oauthLogin,result.data);clearInterval(oauthTimer);oauthTimer=setInterval(pollOAuth,2000)}
async function pollOAuth(){if(!oauthLogin.login_id)return;const result=await getChatGptLoginStatus(oauthLogin.login_id);Object.assign(oauthLogin,result.data);if(oauthLogin.status!=='waiting'){clearInterval(oauthTimer);oauthTimer=null;if(oauthLogin.status==='authenticated'){await refreshOAuthAccount();notice.value='ChatGPT 登录成功';noticeError.value=false}else{notice.value=`ChatGPT 登录状态：${oauthLogin.status}`;noticeError.value=true}}}
async function copyOAuthCode(){await navigator.clipboard.writeText(oauthLogin.user_code);notice.value='授权代码已复制'}
async function logoutOAuth(){if(!window.confirm('确定退出 ChatGPT OAuth 登录吗？'))return;await logoutChatGpt();Object.assign(oauthAccount,{authenticated:false,email:null,plan:null});Object.assign(oauthLogin,{status:'idle',login_id:null,user_code:null,verification_uri:null})}
onMounted(async()=>{await Promise.all([load(),refreshOAuthAccount()])})
onBeforeUnmount(()=>{if(oauthTimer)clearInterval(oauthTimer)})
</script>

<style scoped>
.settings-page{min-height:100vh;background:#f6f6f3;color:#111}.settings-page header{height:70px;padding:0 clamp(20px,5vw,72px);display:flex;align-items:center;justify-content:space-between;background:#fff;border-bottom:1px solid #ddd}.settings-page a{color:#111}.brand{text-decoration:none;font-size:20px;font-weight:800}main{width:min(1180px,calc(100% - 36px));margin:auto;padding:60px 0 100px}.heading,.section-title{display:flex;justify-content:space-between;align-items:flex-end;gap:20px}.heading p{font-size:12px;color:#e85d18;letter-spacing:.14em}.heading h1{font-size:clamp(44px,7vw,80px);letter-spacing:-.06em}.heading button,.save-draft,.connection-form button{min-height:44px;padding:0 20px;background:#111;color:#fff;border:0;cursor:pointer}.notice{margin:24px 0;padding:14px;border:1px solid #2f7d57;background:#f1fff7}.notice[data-error=true]{border-color:#a53b3b;background:#fff3f3}section{margin-top:52px}.section-title{padding-bottom:16px;border-bottom:1px solid #bbb}.section-title div{display:flex;align-items:center;gap:12px}.section-title span{font-size:12px;color:#777}.role-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}.role-grid article{padding:22px;background:#fff;border:1px solid #d6d6d6}.role-mark{font-size:11px;color:#e85d18}.role-grid h3{margin:12px 0 8px}.role-grid p{min-height:42px;color:#666;font-size:13px}.settings-page label{display:grid;gap:7px;margin-top:16px;font-size:12px}.settings-page input,.settings-page select{width:100%;min-height:44px;padding:0 10px;border:1px solid #bbb;background:#fff}.model-select-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:6px}.model-select-row button{min-height:44px;padding:0 10px;border:1px solid #bbb;background:#fff;cursor:pointer}.field-error{color:#a53b3b;line-height:1.5}.settings-page summary{margin-top:18px;cursor:pointer}.check{display:flex!important;grid-template-columns:20px 1fr;align-items:center}.check input{min-height:auto}.save-draft{margin-top:18px}.connection-form{display:grid;grid-template-columns:1fr 1.2fr 2fr 1.3fr auto;gap:8px;margin:18px 0}.connections article{display:flex;justify-content:space-between;flex-wrap:wrap;gap:20px;padding:16px 0;border-bottom:1px solid #ddd}.connections article>div{display:flex;align-items:center;gap:14px;min-width:0}.connections code{overflow-wrap:anywhere}.connections button{min-height:40px;border:0;background:transparent;text-decoration:underline;cursor:pointer}.connections button:disabled{cursor:wait;opacity:.5}.test-result{font-size:12px;color:#666;white-space:nowrap}.test-result[data-status="passed"]{color:#237149}.test-result[data-status="failed"]{color:#a53b3b}.oauth-panel{flex-basis:100%;padding:14px!important;border:1px solid #e85d18;background:#fff8f3;justify-content:flex-start!important}.oauth-panel code{font-size:18px;font-weight:700;letter-spacing:.12em}@media(max-width:800px){.role-grid{grid-template-columns:1fr}.connection-form{grid-template-columns:1fr}.heading,.section-title{align-items:stretch;flex-direction:column}.connections article,.connections article>div{align-items:flex-start;flex-direction:column}.heading button{width:100%}}
</style>
